import{_ as e,o as a,c as n,ag as r}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"第 17 章：多 Agent 协作不是越多越好","description":"适合拆分的任务、角色/边界/共享上下文/交付协议、并行/串行/评审/仲裁模式、成本与风险、何时回到单 Agent；产出双 Agent 协作实验。","frontmatter":{"title":"第 17 章：多 Agent 协作不是越多越好","description":"适合拆分的任务、角色/边界/共享上下文/交付协议、并行/串行/评审/仲裁模式、成本与风险、何时回到单 Agent；产出双 Agent 协作实验。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/17-multi-agent.md","filePath":"guide/17-multi-agent.md","lastUpdated":null}'),l={name:"guide/17-multi-agent.md"};function o(d,t,i,g,s,h){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="第-17-章-多-agent-协作不是越多越好" tabindex="-1">第 17 章：多 Agent 协作不是越多越好 <a class="header-anchor" href="#第-17-章-多-agent-协作不是越多越好" aria-label="Permalink to &quot;第 17 章：多 Agent 协作不是越多越好&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>「一个 Agent 不够，那就上十个」——这是最常见的系统化误区。多 Agent 不是人数优势，而是<strong>分工优势</strong>：只有任务真的能拆、角色真的需要分开、信息传递真的可控时，多 Agent 才划算。本章给你判断标准与四种协作模式，并带你做一次<strong>双 Agent 协作实验</strong>，亲身验证「何时该多、何时该回单」。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>有人搭了一个「专家团队」：10 个 Agent 各扮一个角色，让它们一起写一份报告。结果：Agent A 写的结论和 Agent B 写的结论互相矛盾，Agent C 引用了 A 的错误数据，整份报告返工三遍——比单 Agent 还慢。</p><p><strong>反例</strong>：本书项目的实测里，一款产品（Codex）的审阅视图支持「Agent 起草 → 人审阅 → 提交」的人机协作链路，单 Agent + 人工检查就完成了全部交付，从未动用多 Agent。</p><p><strong>关键判断：多 Agent 解决的是「任务结构问题」，不是「模型能力问题」。</strong> 任务本身拆不开、角色边界不清楚，上再多 Agent 只是把错误复制多份。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>适合拆分的任务特征</strong>：有明显子任务边界、各子任务材料相对独立、子任务结果可以拼接（如：并行调研三个话题 → 汇总）；</li><li><strong>不适合的任务</strong>：高度耦合、需要全局一致、结果互相依赖（如：写一篇前后呼应的长文）——单 Agent 或人工分段更合适；</li><li><strong>四个协议必须定</strong>：角色（谁做什么）、边界（谁不能碰什么）、共享上下文（大家共同看什么）、交付协议（产出物格式与交接点）；</li><li><strong>四种模式</strong>：并行（同时干）、串行（接力干）、评审（一个写一个挑刺）、仲裁（两个方案选一或冲突裁决）；</li><li><strong>回到单 Agent 的信号</strong>：成本膨胀、上下文互相污染、协调开销超过收益——<strong>多 Agent 是手段，不是目的</strong>。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>角色（Role）</strong>：每个 Agent 的职责定义（如「研究员」「写作者」「审阅者」）。白话解释：岗位说明书。</li><li><strong>交付协议（Handoff protocol）</strong>：Agent 之间传递产物的格式与规则（文件放哪、命名、交接点）。白话解释：交接班记录表。</li><li><strong>共享上下文（Shared context）</strong>：所有 Agent 共同依赖的材料与规则（放固定位置，大家引用）。</li><li><strong>上下文污染放大</strong>：多 Agent 下，一个 Agent 的错误输出成为另一个 Agent 的输入——<strong>错误会被复制和放大</strong>（第 14 章杠杆 × 多人）。</li></ul><h2 id="四种协作模式" tabindex="-1">四种协作模式 <a class="header-anchor" href="#四种协作模式" aria-label="Permalink to &quot;四种协作模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>怎么运作</th><th>适合</th><th>风险</th></tr></thead><tbody><tr><td><strong>并行</strong></td><td>各自独立任务，最后汇总</td><td>子任务互相独立</td><td>口径不统一，汇总难</td></tr><tr><td><strong>串行</strong></td><td>A 产出 → B 基于 A 继续</td><td>流水线式流程</td><td>前序错误传导</td></tr><tr><td><strong>评审</strong></td><td>一个做，一个查</td><td>需要质量把关</td><td>审阅者被带偏</td></tr><tr><td><strong>仲裁</strong></td><td>两个方案，人/规则裁决</td><td>关键决策</td><td>裁决成本</td></tr></tbody></table><h2 id="跟着做-一次双-agent-协作实验" tabindex="-1">跟着做：一次双 Agent 协作实验 <a class="header-anchor" href="#跟着做-一次双-agent-协作实验" aria-label="Permalink to &quot;跟着做：一次双 Agent 协作实验&quot;">​</a></h2><h3 id="第一步-选一个「真能拆」的任务" tabindex="-1">第一步：选一个「真能拆」的任务 <a class="header-anchor" href="#第一步-选一个「真能拆」的任务" aria-label="Permalink to &quot;第一步：选一个「真能拆」的任务&quot;">​</a></h3><p>例如：拆成「材料调研（Agent 1）+ 报告撰写（Agent 2）」，材料调研的产出是撰写 Agent 的唯一输入。<strong>不要</strong>选一篇必须整体连贯的抒情长文。</p><h3 id="第二步-定四个协议" tabindex="-1">第二步：定四个协议 <a class="header-anchor" href="#第二步-定四个协议" aria-label="Permalink to &quot;第二步：定四个协议&quot;">​</a></h3><ul><li>角色：Agent 1 = 研究员（输出事实清单），Agent 2 = 写作者（基于清单写报告）；</li><li>边界：Agent 1 只读材料目录，Agent 2 只读 Agent 1 的产出 + 模板；</li><li>共享上下文：任务卡 + CONTEXT.md（放在固定路径，双方引用）；</li><li>交付协议：Agent 1 输出 <code>facts.md</code>（格式固定：事实/来源/置信度），Agent 2 必须基于它撰写，不得自行扩展材料。</li></ul><h3 id="第三步-串行执行并记录" tabindex="-1">第三步：串行执行并记录 <a class="header-anchor" href="#第三步-串行执行并记录" aria-label="Permalink to &quot;第三步：串行执行并记录&quot;">​</a></h3><p>Agent 1 完成 → 人检查 <code>facts.md</code>（<strong>这是关键检查点</strong>：确保错误不传导）→ Agent 2 撰写 → 人验收（第 10 章清单）。</p><h3 id="第四步-对比单-agent" tabindex="-1">第四步：对比单 Agent <a class="header-anchor" href="#第四步-对比单-agent" aria-label="Permalink to &quot;第四步：对比单 Agent&quot;">​</a></h3><p>用同样任务跑一次单 Agent（一次任务卡到底）。比较：总用时、人工介入、结果质量、成本。记录下「多 Agent 值不值」。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><ul><li>任务：整理 10 篇材料 → 输出对比报告（子任务可拆：材料要点抽取 + 报告撰写）；</li><li>单 Agent 做法：一个任务卡，Agent 边读边写，10 分钟完成，一次通过；</li><li>双 Agent 做法：研究员输出 30 条事实 → 人检查发现 2 条来源可疑（阻断传导）→ 写作者成稿 → 总用时 15 分钟 + 1 次人工检查；</li><li>结论：本例中<strong>单 Agent 更划算</strong>——子任务虽可拆，但单 Agent 的上下文足够，多拆反而增加交接成本。<strong>如果材料量 ×5、需要多人同时并行调研，双 Agent 才显优势。</strong></li></ul><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>多 Agent 产出互相矛盾</td><td>口径没统一</td><td>共享上下文里写清口径，加「仲裁」层</td></tr><tr><td>错误被多个 Agent 复制</td><td>前序输出没检查</td><td>每个交接点设人工检查（阻断传导）</td></tr><tr><td>成本翻倍效果持平</td><td>任务不需要拆分</td><td>回到单 Agent，别为「系统感」买单</td></tr><tr><td>Agent 之间互相等</td><td>串行依赖设计差</td><td>改为并行或合并</td></tr><tr><td>不知道谁该对什么负责</td><td>角色边界不清</td><td>交付协议里写清角色与交接物</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>多 Agent 的权限边界要<strong>分别</strong>设置，不要「一个授权全队共享」；</li><li>交接物（facts.md 等）可能包含敏感信息，注意脱敏；</li><li>仲裁场景下，最终裁决权留在人——机器之间的「讨论」不能替你承担责任。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>40 分钟：按「跟着做」完成双 Agent 协作实验（材料调研 + 报告撰写），用「对比单 Agent」的结果记录下你的结论：这个任务该多还是该单，为什么。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>一次双 Agent 协作实验</strong>的记录（四协议 + 交接检查 + 与单 Agent 对比结论）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>多 Agent 解决任务结构问题，不解决模型能力问题；</li><li>适合拆分的任务：子任务独立、材料可分、结果可拼；</li><li>四个协议：角色、边界、共享上下文、交付协议；</li><li>四种模式：并行、串行、评审、仲裁；</li><li>错误会跨 Agent 放大，交接点必须人工检查；多 Agent 是手段不是目的。</li></ol>',34)])])}const c=e(l,[["render",o]]);export{u as __pageData,c as default};
